(function(root){
  const A=()=>root.DairyAcademy,Art=()=>root.DairyArt;
  function categoryArt(id){return id==='variables'?Art().product('Yogurt'):id==='objectives'?Art().medal():id==='strategies'?Art().machine():Art().academy();}
  function render(data,category='variables',example=0,lab=false){
    const current=A().categories.find(c=>c.id===category)||A().categories[0],ex=A().examples[example]||A().examples[0];
    return `<section class="academy-hero"><div><p class="eyebrow">APRENDE EL IDIOMA DE TU FÁBRICA</p><h1>Academia de Producción</h1><p>Lo que ya haces jugando también tiene un nombre. Explora una idea, prueba un ejemplo y vuelve a la planta.</p><span class="academy-reading">${data.conceptsRead?.length||0} conceptos consultados · todo el contenido está disponible</span></div>${Art().academy()}</section><div class="academy-tabs" role="tablist" aria-label="Temas de la Academia">${A().categories.map(c=>`<button role="tab" id="tab-${c.id}" aria-controls="academy-content" aria-selected="${category===c.id}" data-category="${c.id}">${categoryArt(c.id)}<span>${c.short}</span></button>`).join('')}</div><section id="academy-content" role="tabpanel" aria-labelledby="tab-${current.id}"><div class="section-title"><div><p class="eyebrow">EXPLORA A TU RITMO</p><h2>${current.name}</h2></div><span class="muted">Pulsa una tarjeta para descubrirla</span></div>${category==='notation'?`<section class="notation-lab"><h3>Tres campos, una misión</h3><div class="notation-parts"><span><b>α</b>Máquinas</span><i>|</i><span><b>β</b>Restricciones</span><i>|</i><span><b>γ</b>Objetivo</span></div><div class="example-switch">${A().examples.map((e,i)=>`<button class="${i===example?'primary':'secondary'}" data-example="${i}" aria-pressed="${i===example}">${e.code}</button>`).join('')}</div><div class="example-translation" aria-live="polite"><div>${ex.parts.map((p,i)=>`<span><small>${['α','β','γ'][i]}</small>${p}</span>`).join('')}</div><p>${ex.translation}</p></div></section>`:''}<div class="academy-grid">${A().entries.filter(e=>e.category===category).map(e=>`<button class="academy-card" data-concept="${e.id}"><span class="academy-card-status">${data.conceptsRead?.includes(e.id)?'✓ CONSULTADO':root.DairyProgress.isDiscovered(data,e)?'✦ DESCUBIERTO EN LA FÁBRICA':'POR EXPLORAR'}</span><span class="academy-symbol">${e.symbol}</span><h3>${e.simpleName}</h3><p>${e.name}</p><span class="academy-open">Definición y ejemplo <b>↗</b></span></button>`).join('')}</div></section>${category==='strategies'?`<section class="minilab"><div><p class="eyebrow">PRUEBA SIN PUNTOS NI PENALIZACIONES</p><h2>Dos clientes. ¿Quién va primero?</h2><p>El queso tarda 30 minutos; la leche, 10. Los dos están disponibles a las 08:00.</p><button class="primary" data-action="lab-toggle">⇄ Cambiar el orden</button></div><div class="lab-visual" aria-live="polite"><div class="lab-products">${lab?Art().product('Leche fresca')+Art().product('Queso fresco'):Art().product('Queso fresco')+Art().product('Leche fresca')}</div><div class="lab-bars ${lab?'short-first':''}"><span>${lab?'Leche · 10 min':'Queso · 30 min'}</span><span>${lab?'Queso · 30 min':'Leche · 10 min'}</span></div><b>Finalizaciones: ${lab?'10 + 40 = 50':'30 + 40 = 70'} min</b><p>Ambos órdenes acaban a las 08:40. Cambia cuánto esperan los clientes en conjunto.</p></div></section>`:''}<div class="note-box"><b>Tu progreso y tus puntos</b><p>Una estrella basta para avanzar. Las pistas restan 100 puntos cada una y la primera elimina el bono de 500 por jugar sin pistas; nunca reducen estrellas. Consultar la Academia no penaliza. Ver una solución abre un intento de práctica.</p><details><summary>Cómo medimos la calidad</summary><p>Calidad = max(0, 1 − (tu objetivo − óptimo) / escala) × 100. Escala: Σpj, o Σwjpj para objetivos ponderados, o n para contar tardíos. No es utilización de máquinas. Tres estrellas requieren 98%; dos, 80%.</p><p>Puntos: 1.000 por completar, hasta 5.000 por calidad, hasta 1.000 por puntualidad, 500 sin pistas y 1.000 por óptimo; cada pista resta 100. Las misiones sin fechas tienen 1.000 de iniciación fijos. Máximo: 8.500.</p></details></div>`;
  }
  function concept(id){const e=A().entries.find(e=>e.id===id);if(!e)return '';return `<div class="dialog-heading"><span class="tag">ACADEMIA · ${A().categories.find(c=>c.id===e.category).short.toUpperCase()}</span><button class="icon-button" data-action="close" aria-label="Cerrar concepto">×</button></div><div class="concept-dialog-art">${categoryArt(e.category)}</div><h2 id="dialog-title">${e.simpleName}</h2><p class="concept-english">${e.name}</p><div class="concept-symbol">${e.symbol}</div><p class="concept-definition">${e.definition}</p><div class="concept-example"><b>Un ejemplo en la planta</b><p>${e.example}</p></div><div class="concept-use"><b>¿Cuándo sirve?</b><p>${e.when}</p></div><button class="primary" data-action="close">Entendido · volver</button>`;}
  function exam(level,answers,feedback){return `<section class="exam-intro"><div class="exam-art">${Art().medal()}</div><p class="eyebrow">MISIÓN 13 · EL EXAMEN DEL JEFE DE PLANTA</p><h1>Ahora sabes leer la orden.</h1><p>Hasta aquí aprendiste tomando decisiones. Interpreta la notación de dirección y después organiza la producción.</p><div class="exam-notation">${level.notation}</div><div class="exam-help"><span>Consultar en la Academia:</span> <button class="text-button" data-concept="alpha">Máquinas ⓘ</button> <button class="text-button" data-concept="beta">Restricciones ⓘ</button> <button class="text-button" data-concept="weighted-tardiness">Objetivo ⓘ</button></div><div class="exam-questions">${A().questions.map((q,i)=>`<fieldset><legend>${i+1}. ${q.prompt}</legend>${q.options.map((option,k)=>`<label class="exam-option"><input type="radio" name="exam-${i}" data-question="${i}" value="${k}" ${answers[i]===k?'checked':''} ${feedback?'disabled':''}><span>${String.fromCharCode(65+k)}.</span> ${option}</label>`).join('')}${feedback?`<div class="exam-feedback ${feedback[i].correct?'correct':'incorrect'}"><b>${feedback[i].correct?'✓ Bien interpretado':'↳ Aprendamos de esta respuesta'}</b><p>${feedback[i].explanation}</p></div>`:''}</fieldset>`).join('')}</div>${feedback?`<p class="exam-reassurance">${feedback.filter(f=>f.correct).length} de 3 respuestas correctas. Las explicaciones ya están disponibles: puedes volver a intentarlo o continuar. Este paso no resta puntos.</p><div class="guide-buttons"><button class="secondary" data-action="exam-retry">Repasar preguntas</button><button class="primary" data-action="exam-continue">Entrar a la sala de producción →</button></div>`:`<button class="primary" data-action="exam-check" ${answers.some(a=>a==null)?'disabled':''}>Comprobar mi interpretación →</button><p class="small-note">Selecciona una respuesta por pregunta. Equivocarte también forma parte del aprendizaje.</p>`}</section>`;}
  root.DairyAcademyUI={render,concept,exam};
})(globalThis);
